"""Realistic, deliberately messy enterprise-shaped synthetic dataset —
Real Enterprise Dataset Validation Foundation v0.1, item 9.

**This is SYNTHETIC data. It is not, and must never be described as,
real customer or enterprise data.** No actual organization's records are
used, referenced, or resembled beyond generic industry vocabulary
(near miss, permit-to-work, CMMS, ...) already used elsewhere in this
codebase's own fixtures. Every value below is fabricated, deterministic,
and seeded — see `SYNTHETIC_LABEL` below, which every report generated
from this dataset restates verbatim.

Built the same way `tests/fixtures/enterprise_scenarios.py` is (relative
day-offsets from a caller-supplied `base_time`, `random.Random(seed)`
only, `RawSafetyEventPayload` objects fed through the real ingestion
pipeline) — reusing that module's site/department/contractor/activity
pools and small helpers rather than duplicating them. What makes *this*
fixture different: `enterprise_scenarios.py`'s domain builders always
emit clean, already-canonical `event_type` strings (`"INCIDENT"`,
`"NEAR_MISS"`, ...), because those scenarios exist to calibrate
*intelligence*, not terminology handling. This fixture instead emits the
**raw, varied, sometimes-wrong terminology a real source system would
actually send** — mixed capitalization, abbreviations, ambiguous and
unknown terms, several distinct `source_system` identifiers — plus
every other messy characteristic item 9 asks for: missing values,
duplicates, corrections/version changes, invalid records, out-of-order
arrival, deep historical data, incomplete records, and a future
timestamp.

`build_messy_dataset()` returns the primary, richly messy dataset for
one organization; `build_secondary_dataset()` returns a second, smaller,
cleaner dataset for a *different* organization, used only for
multi-tenant isolation checks (mirroring
`tests/evaluation/calibration_harness.py`'s own two-organization
pattern) — never merged with the primary dataset.
"""

from __future__ import annotations

import random
from dataclasses import dataclass, field
from datetime import datetime, timedelta, timezone

from app.intelligence.schemas import RawSafetyEventPayload
from tests.fixtures.enterprise_scenarios import (
    ACTIVITIES,
    CONTRACTORS,
    DEPARTMENTS,
    SITES,
    _at,
    _iso,
    _record_id,
)

SYNTHETIC_LABEL = (
    "SYNTHETIC — enterprise-shaped fixture data generated by "
    "tests/fixtures/messy_enterprise_dataset.py. Not real customer or "
    "enterprise data. Passing validation against this dataset does not "
    "constitute validation against real customer data."
)

_SOURCE_SYSTEMS = ["legacy-ehs-alpha", "sap-prod-us1", "cmms-east", "incident-tracker-v2"]


@dataclass
class MessyDatasetCharacteristics:
    """The counts this fixture was *constructed* to produce — literal,
    by-hand-counted expectations a test can assert against directly, not
    a second computation over the same data (see
    `tests/test_enterprise_dataset_validation.py`)."""

    total_records: int
    duplicate_in_batch_records: int  # exact replays
    missing_event_time_records: int
    missing_identifier_records: int  # no source_record_id -> REJECTED_INVALID
    invalid_classification_records: int  # unrecognized severity
    version_correction_pairs: int  # v1 -> v2, applied
    version_conflict_pairs: int  # same version, different content
    stale_version_records: int  # an older version arriving after a newer one
    future_timestamp_records: int
    duplicate_timestamp_pairs: int  # two distinct records sharing one event_time
    unknown_event_type_terms: int  # unique unknown event_type source terms
    ambiguous_event_type_terms: int  # unique ambiguous event_type source terms
    unknown_subtype_terms: int
    ambiguous_subtype_terms: int
    distinct_source_systems: int


@dataclass
class MessyEnterpriseDataset:
    label: str
    description: str
    events: list[RawSafetyEventPayload] = field(default_factory=list)
    characteristics: MessyDatasetCharacteristics | None = None


def build_messy_dataset(
    base_time: datetime | None = None, seed: int = 5001, *, primary_site_id=None
) -> MessyEnterpriseDataset:
    """`primary_site_id`, when given, is stamped onto the clean,
    varied-terminology near-miss/incident records only (below) -- a real
    `Site.id` a caller creates first, so provenance/feature/predictive
    validation (item 5-7) has a concrete site to build against, exactly
    like a real integration would send *some* records site-scoped and
    others not. Every other record in this dataset intentionally stays
    `site_id=None`."""
    base_time = base_time or datetime.now(timezone.utc)
    rng = random.Random(seed)
    events: list[RawSafetyEventPayload] = []

    def sys() -> str:
        return rng.choice(_SOURCE_SYSTEMS)

    # --- Clean records, varied terminology styles (all MAPPED) --------------------------
    # Near-miss terminology variety -- exercises the alias table's whitespace/
    # case/punctuation-insensitive matching, not a new capability.
    for term, days_ago in [("Near Miss", 3), ("NM", 40), ("Potential Incident", 75), ("near-miss", 110)]:
        events.append(
            RawSafetyEventPayload(
                event_type=term, event_subtype="Dropped Object", event_time=_iso(_at(base_time, rng, days_ago=days_ago)),
                site_id=primary_site_id, location=rng.choice(SITES), department=rng.choice(DEPARTMENTS),
                contractor=rng.choice(CONTRACTORS), activity=rng.choice(ACTIVITIES), source_system=sys(),
                source_record_id=_record_id("NM", rng),
            )
        )
    for term, days_ago in [("Safety Incident", 5), ("injury", 60)]:
        events.append(
            RawSafetyEventPayload(
                event_type=term, event_subtype="First Aid Case", severity="LOW",
                event_time=_iso(_at(base_time, rng, days_ago=days_ago)),
                site_id=primary_site_id, location=rng.choice(SITES), department=rng.choice(DEPARTMENTS),
                source_system=sys(), source_record_id=_record_id("INC", rng),
            )
        )

    # --- Ambiguous terminology (never guessed -- must quarantine) -----------------------
    ambiguous_event_type_terms = {"finding", "event"}
    for term, days_ago in [("finding", 12), ("finding", 88), ("event", 20)]:
        events.append(
            RawSafetyEventPayload(
                event_type=term, event_time=_iso(_at(base_time, rng, days_ago=days_ago)),
                location=rng.choice(SITES), source_system=sys(), source_record_id=_record_id("AMB", rng),
            )
        )
    ambiguous_subtype_terms = {"damage"}
    events.append(
        RawSafetyEventPayload(
            event_type="INCIDENT", event_subtype="damage", severity="MEDIUM",
            event_time=_iso(_at(base_time, rng, days_ago=15)),
            location=rng.choice(SITES), source_system=sys(), source_record_id=_record_id("AMBSUB", rng),
        )
    )

    # --- Unknown terminology (never guessed) ---------------------------------------------
    unknown_event_type_terms = {"Widget Malfunction", "XYZ-99 Report"}
    for term, days_ago in [("Widget Malfunction", 8), ("Widget Malfunction", 45), ("XYZ-99 Report", 30)]:
        events.append(
            RawSafetyEventPayload(
                event_type=term, event_time=_iso(_at(base_time, rng, days_ago=days_ago)),
                location=rng.choice(SITES), source_system=sys(), source_record_id=_record_id("UNK", rng),
            )
        )
    unknown_subtype_terms = {"mystery condition"}
    events.append(
        RawSafetyEventPayload(
            event_type="Observation", event_subtype="mystery condition",
            event_time=_iso(_at(base_time, rng, days_ago=9)),
            location=rng.choice(SITES), source_system=sys(), source_record_id=_record_id("UNKSUB", rng),
        )
    )

    # --- Missing values --------------------------------------------------------------------
    missing_event_time_records = 2
    for _ in range(missing_event_time_records):
        events.append(
            RawSafetyEventPayload(
                event_type="INCIDENT", event_time=None, source_system=sys(), source_record_id=_record_id("NODATE", rng),
            )
        )
    # Incomplete but valid -- missing severity/description/subtype is not a
    # validation failure, only an absent optional field.
    events.append(
        RawSafetyEventPayload(
            event_type="OBSERVATION", event_time=_iso(_at(base_time, rng, days_ago=6)),
            source_system=sys(), source_record_id=_record_id("INCOMPLETE", rng),
        )
    )

    # --- Invalid classification (unrecognized severity -> PARTIAL) -----------------------
    invalid_classification_records = 1
    events.append(
        RawSafetyEventPayload(
            event_type="INCIDENT", event_subtype="First Aid Case", severity="super-critical-plus",
            event_time=_iso(_at(base_time, rng, days_ago=4)), source_system=sys(), source_record_id=_record_id("BADSEV", rng),
        )
    )

    # --- Missing identifiers (-> REJECTED_INVALID) ------------------------------------------
    missing_identifier_records = 2
    for _ in range(missing_identifier_records):
        events.append(
            RawSafetyEventPayload(
                event_type="INCIDENT", event_time=_iso(_at(base_time, rng, days_ago=2)),
                source_system=sys(), source_record_id=None,
            )
        )

    # --- Duplicate (exact replay -> SKIPPED_IDEMPOTENT) -------------------------------------
    duplicate_original = RawSafetyEventPayload(
        event_type="NEAR_MISS", event_subtype="VEHICLE_NEAR_MISS", event_time=_iso(_at(base_time, rng, days_ago=7)),
        source_system="sap-prod-us1", source_record_id="DUP-ENT-0001",
    )
    events.append(duplicate_original)
    events.append(duplicate_original)  # identical resend

    # --- Corrections / version changes ------------------------------------------------------
    # Built as separate, order-preserving groups (see the shuffle note
    # below) -- each group's *relative* arrival order is exactly what
    # gives it its intended outcome (a correction only updates if the
    # original arrives first; a late stale version only skips if it
    # arrives after the newer one), so these three groups are kept
    # intact even while the rest of the batch is shuffled for realistic
    # out-of-order arrival.
    version_correction_pairs = 1
    correction_group = [
        RawSafetyEventPayload(
            event_type="INCIDENT", event_subtype="FIRST_AID_CASE", description="initial report",
            event_time=_iso(_at(base_time, rng, days_ago=18)), source_record_version="1",
            source_system="cmms-east", source_record_id="CORR-ENT-0001",
        ),
        RawSafetyEventPayload(
            event_type="INCIDENT", event_subtype="FIRST_AID_CASE", description="corrected: additional injury noted",
            event_time=_iso(_at(base_time, rng, days_ago=18)), source_record_version="2",
            source_system="cmms-east", source_record_id="CORR-ENT-0001",
        ),
    ]

    version_conflict_pairs = 1
    conflict_group = [
        RawSafetyEventPayload(
            event_type="INCIDENT", description="account A", event_time=_iso(_at(base_time, rng, days_ago=22)),
            source_record_version="1", source_system="cmms-east", source_record_id="CONFLICT-ENT-0001",
        ),
        RawSafetyEventPayload(
            event_type="INCIDENT", description="conflicting account B", event_time=_iso(_at(base_time, rng, days_ago=22)),
            source_record_version="1", source_system="cmms-east", source_record_id="CONFLICT-ENT-0001",
        ),
    ]

    stale_version_records = 1
    stale_group = [
        RawSafetyEventPayload(
            event_type="INCIDENT", description="v1", event_time=_iso(_at(base_time, rng, days_ago=25)),
            source_record_version="1", source_system="cmms-east", source_record_id="STALE-ENT-0001",
        ),
        RawSafetyEventPayload(
            event_type="INCIDENT", description="v2", event_time=_iso(_at(base_time, rng, days_ago=25)),
            source_record_version="2", source_system="cmms-east", source_record_id="STALE-ENT-0001",
        ),
        RawSafetyEventPayload(  # the late, stale v1 resend -- must be skipped, never re-applied
            event_type="INCIDENT", description="v1 (late resend)", event_time=_iso(_at(base_time, rng, days_ago=25)),
            source_record_version="1", source_system="cmms-east", source_record_id="STALE-ENT-0001",
        ),
    ]

    # --- Future timestamp (plausible, e.g. a scheduled inspection) -----------------------
    future_timestamp_records = 1
    events.append(
        RawSafetyEventPayload(
            event_type="INSPECTION", event_subtype="SITE_INSPECTION", status="SCHEDULED",
            event_time=_iso(base_time + timedelta(days=14)),
            source_system=sys(), source_record_id=_record_id("FUTURE", rng),
        )
    )

    # --- Duplicate timestamps on genuinely distinct records --------------------------------
    shared_time = _iso(_at(base_time, rng, days_ago=10))
    events.append(
        RawSafetyEventPayload(
            event_type="NEAR_MISS", event_subtype="DROPPED_OBJECT", event_time=shared_time,
            source_system=sys(), source_record_id=_record_id("SAMETIME", rng),
        )
    )
    events.append(
        RawSafetyEventPayload(
            event_type="NEAR_MISS", event_subtype="VEHICLE_NEAR_MISS", event_time=shared_time,
            source_system=sys(), source_record_id=_record_id("SAMETIME", rng),
        )
    )

    # --- Deep historical data (well past the milestone-2-style 120-day window) -----------
    for days_ago in (240, 300):
        events.append(
            RawSafetyEventPayload(
                event_type="AUDIT", event_subtype="COMPLIANCE_FINDING",
                event_time=_iso(_at(base_time, rng, days_ago=days_ago)),
                source_system=sys(), source_record_id=_record_id("HIST", rng),
            )
        )

    # --- Training/maintenance status terminology (exercises the two status mappers) -------
    events.append(
        RawSafetyEventPayload(
            event_type="Training", status="Complete", event_time=_iso(_at(base_time, rng, days_ago=5)),
            source_system=sys(), source_record_id=_record_id("TRN", rng),
        )
    )
    events.append(
        RawSafetyEventPayload(
            event_type="Training", status="Past Due", event_time=_iso(_at(base_time, rng, days_ago=3)),
            source_system=sys(), source_record_id=_record_id("TRN", rng),
        )
    )
    events.append(
        RawSafetyEventPayload(
            event_type="Equipment", status="Breakdown", event_time=_iso(_at(base_time, rng, days_ago=6)),
            source_system=sys(), source_record_id=_record_id("EQP", rng),
        )
    )

    # --- Out-of-order arrival: shuffle deterministically, groups intact --------------------
    # (arrival order must never be assumed to match event_time order -- see
    # tests/test_enterprise_temporal_calibration.py's own out-of-order case,
    # which this dataset exercises again at realistic scale/variety). The
    # three version-sequence groups above are inserted at fixed, spread
    # positions *after* shuffling everything else, preserving each
    # group's own internal arrival order -- shuffling within a group
    # would silently change which outcome (UPDATED vs. CREATED,
    # SKIPPED_STALE_VERSION vs. REJECTED_VERSION_CONFLICT) it produces,
    # which must stay exactly what `characteristics` below documents.
    rng.shuffle(events)
    for i, group in enumerate((correction_group, conflict_group, stale_group)):
        insert_at = min(len(events), (i + 1) * len(events) // 4)
        events[insert_at:insert_at] = group

    characteristics = MessyDatasetCharacteristics(
        total_records=len(events),
        duplicate_in_batch_records=1,
        missing_event_time_records=missing_event_time_records,
        missing_identifier_records=missing_identifier_records,
        invalid_classification_records=invalid_classification_records,
        version_correction_pairs=version_correction_pairs,
        version_conflict_pairs=version_conflict_pairs,
        stale_version_records=stale_version_records,
        future_timestamp_records=future_timestamp_records,
        # 2 groups: the deliberate SAMETIME near-miss pair, plus the
        # exact-duplicate resend (DUP-ENT-0001, appended twice) which,
        # being a literal replay of the same payload, naturally shares
        # its own timestamp with itself too.
        duplicate_timestamp_pairs=2,
        unknown_event_type_terms=len(unknown_event_type_terms),
        ambiguous_event_type_terms=len(ambiguous_event_type_terms),
        unknown_subtype_terms=len(unknown_subtype_terms),
        ambiguous_subtype_terms=len(ambiguous_subtype_terms),
        distinct_source_systems=len(_SOURCE_SYSTEMS),
    )
    return MessyEnterpriseDataset(
        label=SYNTHETIC_LABEL,
        description=(
            "Synthetic, deliberately messy enterprise-shaped dataset: varied source "
            "terminology (mapped/ambiguous/unknown), missing values, an exact-duplicate "
            "resend, a version correction, a same-version conflict, a stale late-arriving "
            "version, a future-dated scheduled record, duplicate timestamps, deep "
            "historical records, and out-of-order arrival, across 4 distinct source systems."
        ),
        events=events,
        characteristics=characteristics,
    )


def build_secondary_dataset(base_time: datetime | None = None, seed: int = 5002) -> MessyEnterpriseDataset:
    """A second, smaller, much cleaner dataset for a *different*
    organization — used only to prove multi-tenant isolation (item 12);
    never merged with `build_messy_dataset()`'s own events."""
    base_time = base_time or datetime.now(timezone.utc)
    rng = random.Random(seed)
    events = [
        RawSafetyEventPayload(
            event_type="NEAR_MISS", event_subtype="DROPPED_OBJECT", event_time=_iso(_at(base_time, rng, days_ago=d)),
            location=rng.choice(SITES), source_system="secondary-org-system", source_record_id=_record_id("SEC", rng),
        )
        for d in (2, 9, 16)
    ]
    return MessyEnterpriseDataset(
        label=SYNTHETIC_LABEL,
        description="Synthetic, clean secondary-organization dataset used only for tenant-isolation checks.",
        events=events,
        characteristics=MessyDatasetCharacteristics(
            total_records=len(events), duplicate_in_batch_records=0, missing_event_time_records=0,
            missing_identifier_records=0, invalid_classification_records=0, version_correction_pairs=0,
            version_conflict_pairs=0, stale_version_records=0, future_timestamp_records=0,
            duplicate_timestamp_pairs=0, unknown_event_type_terms=0, ambiguous_event_type_terms=0,
            unknown_subtype_terms=0, ambiguous_subtype_terms=0, distinct_source_systems=1,
        ),
    )
